#!/usr/bin/env bash
# Usage: ./rs.sh N prep_job   Trains and scores an episode with no VOC and with VOC by time, with baselines and videos for both.
N=$1; A=$2; TS=42; EP=$(printf recon_%06d $N); S=/scratch2/exaFLOPs/srl_yam_run/search/$EP; G=base_suma_rtx3090,dell_rtx3090,suma_rtx4090,gigabyte_a5000,asus_a5000,suma_a6000,gigabyte_a6000; BG=big_suma_rtx3090,$G; P=base_suma_rtx3090,dell_rtx3090; cd /scratch2/exaFLOPs/srl_yam_run/pipe
if grep -q "^PREP_DONE $N" p$N-$A.log; then rm -f $S/partial.txt; echo "ep$N gate passed: $(cat $S/pool.txt)"; else python3 pool_best.py $EP; fi
T=$(sbatch --parsable -J tv$N -p $G --export=ALL,CURR=yam_voc_50m,TAG=-voc train.sbatch $N $TS); C=$(sbatch --parsable -J sv$N -p $P --dependency=afterok:$T --export=ALL,ARM=${EP}_voc_s42,DIRN=U-voc-seed42 score.sbatch $N $TS); B=$(sbatch --parsable --qos=big_qos --nice=200 -J av$N -p $BG --export=ALL,CURR=yam_voc_50m,TAG=-voc train_a.sbatch $N $TS); V=$(sbatch --parsable -J vv$N -p $P --dependency=afterany:$C,afterok:$B --export=ALL,UT=-voc,AT=-voc,RN=${EP}_voc,VT=-voc video.sbatch $N $TS); echo "$N $T $C $B $V" >> voc_rerun.ids
T0=$(sbatch --parsable --qos=big_qos -J t${N}s$TS -p $BG train.sbatch $N $TS); C0=$(sbatch --parsable -J s${N}s$TS -p $P --dependency=afterok:$T0 score.sbatch $N $TS); B0=$(sbatch --parsable --qos=big_qos --nice=200 -J a${N}s$TS -p $BG train_a.sbatch $N $TS); V0=$(sbatch --parsable -J v$N -p $P --dependency=afterany:$C0,afterok:$B0 video.sbatch $N $TS); echo "ep$N VOC $T no-VOC $T0 videos $V $V0"
